+        <input type="tel" class="form-control" @bind="Model.Phone" placeholder="(555) 123-4567" />
+    </div>
+    <div class="col-md-6">
+        <label class="form-label">Address <span class="text-danger">*</span></label>
+        <input class="form-control" @bind="Model.Address" placeholder="123 Main St, City, State" />
+    </div>
+</div>
+
+<div class="d-flex justify-content-end mt-4">
+    <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
+        @if (isValidating)
+        {
+            <span class="spinner-border spinner-border-sm me-1"></span>
+            <span>Validating…</span>
+        }
+        else
+        {
+            <span>Next</span>
+        }
+    </button>
+</div>
+
+@code {
+    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
+    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
+    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;
+
+    private string? errorMessage;
+    private bool isValidating;
+
+    private async Task HandleNext()
+    {
+        errorMessage = null;
+
+        if (!Model.IsValid())
+        {
+            errorMessage = "Please fill in all required fields.";
+            return;
+        }
+
+        isValidating = true;
+        try
+        {
+            var emailValid = await ApplicationService.ValidateEmailAsync(Model.Email.Trim());
+            if (!emailValid)
+            {
+                errorMessage = "The email address could not be validated. Please check and try again.";
+                return;
+            }
+
+            await OnNext.InvokeAsync();
+        }
+        finally
+        {
+            isValidating = false;
+        }
+    }
+}
+

